import { readFile, writeFile } from "node:fs/promises";
import { createBucket, put, list } from "@tigrisdata/storage";

async function main() {
  const trialIdRaw = await readFile("/logs/artifacts/trial_id", "utf-8");
  const trialId = trialIdRaw.trim();

  // Normalize bucket name
  // S3 bucket names can only contain lowercase letters, numbers, dots, and hyphens.
  const normalizedTrialId = trialId.toLowerCase().replace(/[^a-z0-9.-]/g, "-");
  const bucketName = `harbor-tssdk-${normalizedTrialId}`;

  // 1. Create bucket
  const createBucketRes = await createBucket(bucketName);
  if (createBucketRes.error) {
    const errMsg = createBucketRes.error.message?.toLowerCase() || "";
    const isAlreadyExists = errMsg.includes("already exists") || 
                            errMsg.includes("alreadyowned") || 
                            errMsg.includes("conflict") ||
                            errMsg.includes("bucketalready");
    if (!isAlreadyExists) {
      console.error("Error creating bucket:", createBucketRes.error);
      process.exit(1);
    }
  }

  // 2. Put objects
  const messages = [
    { path: "inbox/msg-1.json", body: '{"id": 1}' },
    { path: "inbox/msg-2.json", body: '{"id": 2}' },
    { path: "inbox/msg-3.json", body: '{"id": 3}' },
  ];

  for (const msg of messages) {
    const putRes = await put(msg.path, msg.body, {
      contentType: "application/json",
      config: { bucket: bucketName }
    });
    if (putRes.error) {
      console.error(`Error putting object ${msg.path}:`, putRes.error);
      process.exit(1);
    }
  }

  // 3. List objects
  const listRes = await list({
    prefix: "inbox/",
    config: { bucket: bucketName }
  });

  if (listRes.error) {
    console.error("Error listing objects:", listRes.error);
    process.exit(1);
  }

  const items = listRes.data?.items || [];
  const names = items.map(item => item.name);

  await writeFile("/home/user/tigris-task/listing.txt", names.join("\n"));
  console.log("Done.");
}

main().catch(err => {
  console.error("Unhandled error:", err);
  process.exit(1);
});
